393	/// Recover the statically-asserted type from a Go `x.(T).M()` call.
394	///
395	/// The grammar for `type_assertion_expression` (tree-sitter-go §primary):
396	/// `operand '.' '(' type ')'`. The `type` field is any `_type`, including
397	/// `parenthesized_type` (`(T)`), `pointer_type` (`*T`), `qualified_type`
398	/// (`pkg.T`), or `type_identifier` (`T`).
399	///
400	/// Normalization:
401	/// - `parenthesized_type` is unwrapped one level at a time.
402	/// - `peel_type` strips `*` (pointer); `owner_key` strips the remaining `::` paths.
403	/// - `pkg.T` is NOT stripped here — `iface_key` handles that at route time in
404	///   `resolve_call_site` so owner-lookup routes correctly for concrete types too.
405	///
406	/// Deferred gap (D2): cross-package concrete `pkg.T` where `T` is not an interface
407	/// will fail `owner_lookup` (key `"pkg.T"` has no owner entry). Recorded in spec §D2.
408	fn recover_type_assertion(ctx: &ReceiverCtx<'_>) -> Option<RecoveredReceiver> {
409	    use crate::languages::Language;
410	    if ctx.parsed.language != Language::Go {
411	        return None;
412	    }
413	    let node = ctx.receiver_expr?;
414	    if node.kind() != "type_assertion_expression" {
415	        return None;
416	    }
417	    let mut ty = node.child_by_field_name("type")?;
418	    // Unwrap parenthesized_type: `(T)` → `T` (handles `x.((Runner)).M()`)
419	    while ty.kind() == "parenthesized_type" {
420	        ty = ty.named_child(0)?;
421	    }
422	    // Same normalization as the legacy path → consistent routing: an interface
423	    // (`Runner`/`pkg.Module`) routes via iface_key→interface_impls; a same-package
424	    // concrete (`*Fast`) owner_lookup-resolves. Cross-package concrete `pkg.T`
425	    // does NOT owner-resolve (owner_key keeps `pkg.`) — deferred gap D2.
426	    let static_type = owner_key(&peel_type(ctx.parsed.node_text(&ty)));
427	    if static_type.is_empty() {
428	        return None;
429	    }
430	    Some(RecoveredReceiver {
431	        static_type,
432	        recovery: ReceiverRecovery::TypeAssertion,
433	    })
434	}
