                {
                    let Some(ty) = param.child_by_field_name("type") else {
                        continue;
                    };
                    if self.parameter_binds_name_before_type(param, ty, receiver) {
                        found = Some((
                            self.node_text(&ty).to_string(),
                            ReceiverRecovery::TypedParam,
                        ));
                        bindings += 1;
                    }
