                                qualifier_node,
                                arg_count,
                                arg_spread,
                            ));
                        }
                    }
                }
            }
        }
        return calls;
    }

    let mut calls = Vec::new();
    self.collect_calls_manual_with_qualifier_and_spans(*func_node, lines, &mut calls);
    calls
}

