use prism::call_graph::{CallKind, CallSite};
use prism::navigation::call_resolve::resolve_site_nav;
use prism::navigation::module_graph::{module_deps, repo_map};
use prism::navigation::queries;
use prism::navigation::types::SymbolRef;
use prism::navigation::{NavigationIndex, NavigationSession};
use prism::repo_loader::load_repo;
use std::sync::Arc;

fn session(files: &[(&str, &str)]) -> NavigationSession {
    let dir = tempfile::tempdir().unwrap();
    for (name, src) in files {
        let path = dir.path().join(name);
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent).unwrap();
        }
        std::fs::write(path, src).unwrap();
    }
    let repo = Arc::new(load_repo(dir.path()).unwrap());
    let index = Arc::new(NavigationIndex::build(&repo));
    NavigationSession { repo, index }
}

fn resolved_targets(
    s: &NavigationSession,
    callee_name: &str,
    caller_file: &str,
    qualifier: Option<&str>,
) -> Vec<(String, String)> {
    let cg = &s.index.cpg.call_graph;
    let site = cg
        .calls
        .values()
        .flatten()
        .find(|site| {
            site.caller.file == caller_file
                && site.callee_name == callee_name
                && site.qualifier.as_deref() == qualifier
        })
        .cloned()
        .unwrap_or_else(|| {
            let caller = cg
                .functions
                .values()
                .flatten()
                .find(|fid| fid.file == caller_file)
                .unwrap()
                .clone();
            CallSite {
                caller,
                callee_name: callee_name.to_string(),
                line: 1,
                kind: CallKind::Call,
                start_byte: 0,
                end_byte: 0,
                qualifier: qualifier.map(str::to_string),
                receiver_type: None,
                receiver_recovery: None,
                arg_count: None,
                arg_spread: false,
                receiver_outcome: None,
            }
        });
    resolve_site_nav(cg, &site)
        .into_iter()
        .map(|edge| (edge.target.file.clone(), edge.target.name.clone()))
        .collect()
}

fn resolves_to(
    s: &NavigationSession,
    callee_name: &str,
    caller_file: &str,
    target_file: &str,
    target_name: &str,
) -> bool {
    resolved_targets(s, callee_name, caller_file, None)
        .iter()
        .any(|(file, name)| file == target_file && name == target_name)
}

fn resolves_empty(s: &NavigationSession, callee_name: &str, caller_file: &str) -> bool {
    resolved_targets(s, callee_name, caller_file, None).is_empty()
}

#[test]
fn scoped_mod_fn_resolves_cross_file_rust() {
    let s = session(&[
        ("algo.rs", "pub fn run() -> i32 { 1 }\n"),
        (
            "main.rs",
            "mod algo;\nfn dispatch() -> i32 { algo::run() }\n",
        ),
    ]);
    assert!(
        resolves_to(&s, "algo::run", "main.rs", "algo.rs", "run"),
        "algo::run should resolve to algo.rs::run, got {:?}",
        resolved_targets(&s, "algo::run", "main.rs", None)
    );
}

#[test]
fn scoped_ns_fn_resolves_cross_file_cpp() {
    // C++ namespace-qualified call: util::helper() -> util.cpp::helper (same `::` gap as Rust).
    let s = session(&[
        (
            "util.cpp",
            "namespace util { int helper() { return 1; } }\n",
        ),
        (
            "main.cpp",
            "namespace util { int helper(); }\nint dispatch() { return util::helper(); }\n",
        ),
    ]);
    assert!(
        resolves_to(&s, "util::helper", "main.cpp", "util.cpp", "helper"),
        "util::helper should resolve to util.cpp::helper, got {:?}",
        resolved_targets(&s, "util::helper", "main.cpp", None)
    );
}

#[test]
fn scoped_call_to_wrong_stem_does_not_resolve() {
    let s = session(&[
        ("algo.rs", "pub fn run() -> i32 { 1 }\n"),
        ("main.rs", "fn dispatch() -> i32 { nope::run() }\n"),
    ]);
    assert!(resolves_empty(&s, "nope::run", "main.rs"));
}

#[test]
fn reserved_keyword_hints_do_not_resolve() {
    // A decoy file named `crate.rs`/`self.rs` must NOT satisfy crate::run / self::run.
    let s = session(&[
        ("crate.rs", "pub fn run() -> i32 { 1 }\n"),
        ("self.rs", "pub fn go() -> i32 { 1 }\n"),
        ("main.rs", "fn d() -> i32 { crate::run() + self::go() }\n"),
    ]);
    assert!(resolves_empty(&s, "crate::run", "main.rs"));
    assert!(resolves_empty(&s, "self::go", "main.rs"));
}

#[test]
fn external_crate_path_does_not_resolve_without_stem_match() {
    // bincode::serialize with NO bincode-stem file -> empty (external crate, not in repo).
    let s = session(&[
        ("main.rs", "fn d() { bincode::serialize(); }\n"),
        ("other.rs", "pub fn serialize() -> i32 { 1 }\n"), // decoy: wrong stem, must not match
    ]);
    assert!(resolves_empty(&s, "bincode::serialize", "main.rs"));
}

#[test]
fn multi_segment_scoped_path_uses_last_module_segment() {
    let s = session(&[
        ("algo.rs", "pub fn run() -> i32 { 1 }\n"),
        (
            "main.rs",
            "mod algo;\nfn d() -> i32 { crate::algo::run() }\n",
        ),
    ]);
    assert!(resolves_to(
        &s,
        "crate::algo::run",
        "main.rs",
        "algo.rs",
        "run"
    ));
}

#[test]
fn unscoped_resolution_is_unchanged() {
    let s = session(&[
        ("util.rs", "pub fn helper() -> i32 { 1 }\n"),
        (
            "main.rs",
            "mod util;\nuse util::helper;\nfn run() -> i32 { helper() }\n",
        ),
    ]);
    assert!(resolves_to(&s, "helper", "main.rs", "util.rs", "helper"));
}

#[test]
fn callees_resolves_scoped_dispatch() {
    let s = session(&[
        ("algo.rs", "pub fn run() -> i32 { 1 }\n"),
        (
            "main.rs",
            "mod algo;\nfn dispatch() -> i32 { algo::run() }\n",
        ),
    ]);
    let ev = queries::callees(&s, Some("dispatch"), None, None, 1).unwrap();
    assert!(
        ev.items.iter().any(|it| it
            .symbol
            .as_ref()
            .map(|s| matches!(
                s, SymbolRef::Function { file, name, .. } if file == "algo.rs" && name == "run"
            ))
            .unwrap_or(false)),
        "callees(dispatch) should include scoped callee algo.rs::run"
    );
}

#[test]
fn module_deps_and_repo_map_include_scoped_edge() {
    let s = session(&[
        ("algo.rs", "pub fn run() -> i32 { 1 }\n"),
        (
            "main.rs",
            "mod algo;\nfn dispatch() -> i32 { algo::run() }\n",
        ),
    ]);
    let md = module_deps(&s, "main.rs");
    assert!(
        md.items.iter().any(|it| it.location.file == "algo.rs"),
        "module-deps(main.rs) should include a scoped edge to algo.rs"
    );
    // repo-map shares collect_module_edges -> the edge must appear there too.
    let rm = repo_map(&s);
    let g = rm.graph.as_ref().unwrap();
    let main_i = g
        .nodes
        .iter()
        .position(|n| n.location.file == "main.rs")
        .unwrap();
    let algo_i = g
        .nodes
        .iter()
        .position(|n| n.location.file == "algo.rs")
        .unwrap();
    assert!(g
        .edges
        .iter()
        .any(|e| e.from == main_i && e.to == algo_i && e.kind == "ModuleDep"));
}

#[test]
fn callers_finds_scoped_dispatcher() {
    let s = session(&[
        ("algo.rs", "pub fn run() -> i32 { 1 }\n"),
        (
            "main.rs",
            "mod algo;\nfn dispatch() -> i32 { algo::run() }\n",
        ),
    ]);
    let ev = queries::callers(&s, Some("run"), Some("algo.rs"), None, 1).unwrap();
    assert!(
        ev.items.iter().any(|it| it
            .symbol
            .as_ref()
            .map(|s| matches!(
                s, SymbolRef::Function { name, .. } if name == "dispatch"
            ))
            .unwrap_or(false)),
        "callers(run@algo.rs) should include the scoped dispatcher"
    );
}

#[test]
fn callers_excludes_other_stem_scoped_call() {
    // Two files define `run`; dispatcher calls other::run. callers(run@algo.rs)
    // must NOT include it — scoped_caller_sites returns a superset the identity
    // filter prunes (the Rust/C++ stem-collision guard).
    let s = session(&[
        ("algo.rs", "pub fn run() -> i32 { 1 }\n"),
        ("other.rs", "pub fn run() -> i32 { 2 }\n"),
        (
            "main.rs",
            "mod algo;\nmod other;\nfn dispatch() -> i32 { other::run() }\n",
        ),
    ]);
    let ev = queries::callers(&s, Some("run"), Some("algo.rs"), None, 1).unwrap();
    assert!(
        !ev.items.iter().any(|it| it
            .symbol
            .as_ref()
            .map(|s| matches!(
                s, SymbolRef::Function { name, .. } if name == "dispatch"
            ))
            .unwrap_or(false)),
        "callers(run@algo.rs) must exclude a dispatcher that calls other::run"
    );
}

//! The disproof seam (spec §3): a sound candidate-elimination primitive shared by
//! owner-keyed call resolution.
//!
//! A [`DisproofPredicate`] **proves a candidate is not the callee at a site**; it
//! must be sound — return "not disproved" whenever uncertain. [`prune`] composes
//! predicates by **intersection**: a candidate survives unless *some* predicate
//! disproves it. Recall-safe by construction (P1): adding predicates can only
//! shrink the surviving set, never wrongly drop the true target, and a prune that
//! would empty a non-empty pool returns the ORIGINAL pool (no-confidence, never a
//! drop).
//!
//! This slice ships exactly one predicate — [`ScopeResolution`] (in `resolution.rs`,
//! wired in Task 5). The seam is the extensibility deliverable: future
//! precision-recovery (reachability, arity, receiver-type, trait-bound) becomes new
//! predicates composed into the same intersection.

use crate::call_graph::{CallSite, FunctionId};
use crate::name_resolution::graph::ScopeGraph;
use crate::name_resolution::types::{FileId, ScopeId};

/// Read-only context a [`DisproofPredicate`] may consult. Borrows the scope graph
/// and the call site's already-resolved enclosing scope (the `(file, from)` the
/// caller computed via `rust_authoritative_scope`), so a predicate need not
/// recompute authority.
#[derive(Clone, Copy)]
pub struct DisproofCx<'a> {
    /// The whole-repo scope graph (authoritative — the caller gated on `complete`).
    pub graph: &'a ScopeGraph,
    /// The call site's containing file in the graph.
    pub file: FileId,
    /// The call site's enclosing lexical scope (from `enclosing_scope`).
    pub from: ScopeId,
}

/// A sound disproof predicate.
///
/// SOUND iff `disproves` returns `true` ONLY when it can prove `cand` is not the
/// target at `site`. Implementations must return `false` (not disproved) on any
/// uncertainty.
pub trait DisproofPredicate {
    fn disproves(&self, cand: &FunctionId, site: &CallSite, cx: &DisproofCx<'_>) -> bool;
}

/// Prune `pool` to the candidates no predicate disproves.
///
/// Intersection semantics: a candidate is kept unless *some* predicate disproves
/// it. If pruning would empty a non-empty `pool`, the ORIGINAL `pool` is returned
/// — a disproof that eliminates everything is treated as no-confidence (P1), never
/// a drop. An empty input `pool` returns empty.
pub fn prune<'a>(
    pool: Vec<&'a FunctionId>,
    site: &CallSite,
    cx: &DisproofCx<'_>,
    preds: &[&dyn DisproofPredicate],
) -> Vec<&'a FunctionId> {
    if pool.is_empty() {
        return pool;
    }
    let kept: Vec<&'a FunctionId> = pool
        .iter()
        .copied()
        .filter(|cand| !preds.iter().any(|p| p.disproves(cand, site, cx)))
        .collect();
    if kept.is_empty() {
        pool
    } else {
        kept
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::call_graph::FunctionId;
    use crate::name_resolution::graph::ScopeGraph;
    use crate::name_resolution::types::{FileId, ScopeId};

    fn fid(name: &str) -> FunctionId {
        FunctionId {
            file: "a.rs".to_string(),
            name: name.to_string(),
            start_line: 1,
            end_line: 1,
        }
    }

    fn dummy_site() -> CallSite {
        CallSite {
            caller: fid("caller"),
            callee_name: "Foo::m".to_string(),
            line: 1,
            kind: Default::default(),
            start_byte: 0,
            end_byte: 0,
            qualifier: None,
            receiver_type: None,
            receiver_recovery: None,
            arg_count: None,
            arg_spread: false,
            receiver_outcome: None,
        }
    }

    fn dummy_cx(graph: &ScopeGraph) -> DisproofCx<'_> {
        DisproofCx {
            graph,
            file: FileId(0),
            from: ScopeId(0),
        }
    }

    /// A trivial predicate that disproves exactly the candidates whose name is in
    /// its deny-list. Used to validate the seam mechanics (not shipped).
    struct DenyNames(Vec<String>);
    impl DisproofPredicate for DenyNames {
        fn disproves(&self, cand: &FunctionId, _site: &CallSite, _cx: &DisproofCx<'_>) -> bool {
            self.0.contains(&cand.name)
        }
    }

    #[test]
    fn prune_keeps_undisproved_candidates() {
        let graph = ScopeGraph::new();
        let a = fid("keep_a");
        let b = fid("deny_b");
        let pool = vec![&a, &b];
        let pred = DenyNames(vec!["deny_b".to_string()]);
        let kept = prune(pool, &dummy_site(), &dummy_cx(&graph), &[&pred]);
        assert_eq!(kept, vec![&a], "only the disproved candidate is removed");
    }

    #[test]
    fn prune_to_empty_returns_original_pool() {
        // P1: a prune that eliminates EVERYTHING is no-confidence → keep the
        // original pool, never a drop.
        let graph = ScopeGraph::new();
        let a = fid("deny_a");
        let b = fid("deny_b");
        let pred = DenyNames(vec!["deny_a".to_string(), "deny_b".to_string()]);
        let kept = prune(vec![&a, &b], &dummy_site(), &dummy_cx(&graph), &[&pred]);
        assert_eq!(
            kept,
            vec![&a, &b],
            "prune-to-empty returns the original pool"
        );
    }

    #[test]
    fn prune_with_no_predicates_is_identity() {
        let graph = ScopeGraph::new();
        let a = fid("a");
        let b = fid("b");
        let kept = prune(vec![&a, &b], &dummy_site(), &dummy_cx(&graph), &[]);
        assert_eq!(kept, vec![&a, &b]);
    }

    #[test]
    fn prune_empty_input_is_empty() {
        let graph = ScopeGraph::new();
        let pred = DenyNames(vec![]);
        let kept: Vec<&FunctionId> = prune(Vec::new(), &dummy_site(), &dummy_cx(&graph), &[&pred]);
        assert!(kept.is_empty());
    }

    #[test]
    fn prune_intersection_across_two_predicates() {
        // A candidate survives only if NO predicate disproves it.
        let graph = ScopeGraph::new();
        let a = fid("a");
        let b = fid("b");
        let c = fid("c");
        let p1 = DenyNames(vec!["b".to_string()]);
        let p2 = DenyNames(vec!["c".to_string()]);
        let kept = prune(
            vec![&a, &b, &c],
            &dummy_site(),
            &dummy_cx(&graph),
            &[&p1, &p2],
        );
        assert_eq!(kept, vec![&a]);
    }
}

