    let cg = graph(&[(
        "svc.py",
        "class Foo:\n    def m(self):\n        pass\ndef run():\n    x = Foo(); x.m()\n",
    )]);
    let s = site(&cg, "run", "m");
    assert_eq!(s.receiver_type.as_deref(), Some("Foo"));
}

